 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Each 2x2 block is surrounded by outward diagonal rays originating
    # from the four colored cells immediately adjacent to it.
    # Infer centers from contiguous 2x2 blocks, then rays continue from the
    # marker corners on each side, coloring empty diagonal cells.
    blocks=[]
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[rr][cc]==2 for rr in (r,r+1) for cc in (c,c+1)):
                blocks.append((r,c))
    for r,c in blocks:
        # Color rays are supported by local marker placements; extend each
        # nonzero marker diagonally away from the nearest block.
        for rr in range(h):
            for cc in range(w):
                color=grid[rr][cc]
                if color in (3,6,7,8):
                    # Only markers aligned to a 2x2 motif corner seed its rays.
                    if not any(abs((rr-(br if rr<br else br+1)))<=1 and abs((cc-(bc if cc<bc else bc+1)))<=1 for br,bc in blocks):
                        continue
                    dr=-1 if rr < r else 1; dc=-1 if cc < c else 1
                    y,x=rr+dr,cc+dc
                    while 0<=y<h and 0<=x<w:
                        if out[y][x]==0: out[y][x]=color
                        y+=dr;x+=dc
    return out
